package com.ecoriego.app.ui;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.ecoriego.app.R;import com.ecoriego.app.data.DBHelper;import com.ecoriego.app.adapter.PlantaAdapter;import com.ecoriego.app.model.Planta;import com.ecoriego.app.network.WeatherService;import java.util.*;import android.content.SharedPreferences;
public class MainActivity extends AppCompatActivity{DBHelper db;PlantaAdapter ad;TextView temp,rain,status,resumen;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);db=new DBHelper(this);temp=findViewById(R.id.tvTemp);rain=findViewById(R.id.tvRain);status=findViewById(R.id.tvWeatherStatus);resumen=findViewById(R.id.tvResumen);RecyclerView rv=findViewById(R.id.recyclerPlantas);rv.setLayoutManager(new LinearLayoutManager(this));ad=new PlantaAdapter(new ArrayList<>(),p->{Intent i=new Intent(this,PlantaDetalleActivity.class);i.putExtra("id",p.getId());startActivity(i);});rv.setAdapter(ad);findViewById(R.id.btnNueva).setOnClickListener(v->startActivity(new Intent(this,PlantaFormActivity.class)));findViewById(R.id.btnReportes).setOnClickListener(v->startActivity(new Intent(this,ReportesActivity.class)));cargar();SharedPreferences pref=getSharedPreferences("weather",MODE_PRIVATE);ad.setRainChance(pref.getInt("rain",0));WeatherService.fetch(new WeatherService.Callback(){public void onResult(double t,int r){temp.setText(String.format(Locale.getDefault(),"%.1f°C",t));rain.setText("Lluvia " + r + "%");getSharedPreferences("weather",MODE_PRIVATE).edit().putFloat("temp",(float)t).putInt("rain",r).apply();ad.setRainChance(r);status.setText(r>=60?"Hay alta probabilidad de lluvia hoy. Ajusta el riego.":"Condiciones secas. Revisa las plantas que estén pendientes.");}public void onError(String m){status.setText(m);}});}private void cargar(){List<Planta> l=db.listarPlantas();ad.setData(l);resumen.setText(l.size()+ (l.size()==1?" planta registrada":" plantas registradas"));}@Override protected void onResume(){super.onResume();if(db!=null)cargar();}}
